-- Theme colours generated by scripts/gen-colors.py from the DMS palette (wal without DMS).
-- Falls back to a neutral dark palette when the generated file is missing or
-- unreadable, so the session still starts before the first generation.

local THEME_FILE = "/home/alexis/.cache/hypr-theme/colors.lua"
local BORDERS_FILE = "/home/alexis/.cache/hypr-theme/borders.lua"

local FALLBACK = {
  background = "#101216", foreground = "#c8c8c8",
  active = "#c8c8c8", active_alt = "#6a9fb5",
  inactive = "#101216", inactive_alt = "#4a5560",
  claude_label = "#b58fc0", claude_done = "#82c982", claude_action = "#c99482",
  wallpaper = "",
}

local M = {}

M.colors = FALLBACK

local chunk = loadfile(THEME_FILE)
if chunk then
  local ok, loaded = pcall(chunk)
  if ok and type(loaded) == "table" then
    M.colors = setmetatable(loaded, { __index = FALLBACK })
  end
end

-- Window frames generated by scripts/gen-borders.py, keyed by style name; empty
-- until the first generation.
M.borders = {}

local borders_chunk = loadfile(BORDERS_FILE)
if borders_chunk then
  local ok, loaded = pcall(borders_chunk)
  if ok and type(loaded) == "table" then
    M.borders = loaded
  end
end

local function rgb(hex)
  local r, g, b = hex:match("^#(%x%x)(%x%x)(%x%x)$")
  return tonumber(r, 16), tonumber(g, 16), tonumber(b, 16)
end

-- Text colour readable on `bg`: same rule as the status bar segments.
function M.text_on(bg)
  local r1, g1, b1 = rgb(bg)
  local r2, g2, b2 = rgb(M.colors.foreground)
  local contrast = math.abs(r1 - r2) + math.abs(g1 - g2) + math.abs(b1 - b2)
  if contrast > 280 then
    return M.colors.foreground
  end
  return M.colors.background
end

return M
